import json
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def parse_date(date_str):
    """Parse date from various formats and return as YYYY-MM-DD string or None."""
    if not date_str or not date_str.strip():
        return None

    date_str = date_str.strip()

    # Try YYYYMMDD format (most common in this data)
    if len(date_str) == 8 and date_str.isdigit():
        try:
            dt = datetime.strptime(date_str, "%Y%m%d")
            return dt.strftime("%Y-%m-%d")
        except ValueError:
            pass

    # Try YYYY-MM-DD format
    try:
        dt = datetime.strptime(date_str, "%Y-%m-%d")
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        pass

    # Try other common formats if needed
    formats = ["%m/%d/%Y", "%d/%m/%Y", "%Y/%m/%d", "%b %d, %Y", "%B %d, %Y"]
    for fmt in formats:
        try:
            dt = datetime.strptime(date_str, fmt)
            return dt.strftime("%Y-%m-%d")
        except ValueError:
            continue

    return None

def load_fda_data(packet_dir):
    """Load FDA enforcement reports from JSON file."""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r', encoding='utf-8') as f:
        data = json.load(f)
    # Create mapping from recall_number to record
    records = {}
    for record in data.get("results", []):
        recall_num = record.get("recall_number", "")
        if recall_num:
            records[recall_num] = record
    return records

def extract_fact_value(record, fact_name, rule_id):
    """Extract fact value from record based on fact name and rule."""
    if rule_id == "fda.classified_30d":
        if fact_name == "initiation date":
            raw_value = record.get("recall_initiation_date", "")
        elif fact_name == "classification date":
            raw_value = record.get("center_classification_date", "")
    elif rule_id == "fda.terminated_180d":
        if fact_name == "initiation date":
            raw_value = record.get("recall_initiation_date", "")
        elif fact_name == "termination date":
            raw_value = record.get("termination_date", "")
    else:
        raw_value = ""

    # Parse the date to YYYY-MM-DD format
    parsed_date = parse_date(raw_value)
    return parsed_date

def process_pair(recall_num, rule_id, records):
    """Process a single pair (rule_id::recall_num) and return fact values."""
    if recall_num not in records:
        # No record found for this recall number
        return None

    record = records[recall_num]
    fact_values = {}

    # Extract values for each fact based on rule
    if rule_id == "fda.classified_30d":
        init_date = extract_fact_value(record, "initiation date", rule_id)
        class_date = extract_fact_value(record, "classification date", rule_id)

        if init_date is None:
            fact_values["initiation date"] = "ABSENT"
        else:
            fact_values["initiation date"] = [init_date, "fda_enforcement_reports"]

        if class_date is None:
            fact_values["classification date"] = "ABSENT"
        else:
            fact_values["classification date"] = [class_date, "fda_enforcement_reports"]

    elif rule_id == "fda.terminated_180d":
        init_date = extract_fact_value(record, "initiation date", rule_id)
        term_date = extract_fact_value(record, "termination date", rule_id)

        if init_date is None:
            fact_values["initiation date"] = "ABSENT"
        else:
            fact_values["initiation date"] = [init_date, "fda_enforcement_reports"]

        if term_date is None:
            fact_values["termination date"] = "ABSENT"
        else:
            fact_values["termination date"] = [term_date, "fda_enforcement_reports"]

    return fact_values

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    # Load FDA data
    records = load_fda_data(packet_dir)

    # Process each pair
    result = {}
    for pair in manifest["pairs"]:
        rule_id, recall_num = pair.split("::", 1)
        fact_values = process_pair(recall_num, rule_id, records)

        if fact_values is None:
            # No record found, all facts are ABSENT
            fact_names = manifest["facts"][rule_id]
            result[pair] = {fact: "ABSENT" for fact in fact_names}
        else:
            result[pair] = fact_values

    # Output result as JSON
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

