import json
import os
import sys
from datetime import datetime, timedelta
from collections import defaultdict

def parse_date(date_str):
    """Parse date string in YYYYMMDD format to datetime.date object."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        return datetime.strptime(date_str.strip(), "%Y%m%d").date()
    except ValueError:
        return None

def load_fda_data(packet_dir):
    """Load FDA enforcement reports from JSON file."""
    file_path = os.path.join(packet_dir, "fda_enforcement_reports.json")
    with open(file_path, 'r') as f:
        data = json.load(f)
    return data.get("results", [])

def process_pairs(packet_dir, manifest):
    """Process all pairs in the manifest and return results."""
    # Load FDA data
    fda_records = load_fda_data(packet_dir)

    # Group records by recall number
    records_by_recall = defaultdict(list)
    for record in fda_records:
        recall_num = record.get("recall_number", "")
        if recall_num:
            records_by_recall[recall_num].append(record)

    # Initialize results dictionary
    results = {}

    # Process each pair
    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::")
        facts_needed = manifest["facts"][rule_id]

        # Get all records for this recall number
        records = records_by_recall.get(entity, [])

        # Initialize fact values for this pair
        fact_values = {}

        for fact in facts_needed:
            if fact == "initiation date":
                values = set()
                for rec in records:
                    date_val = rec.get("recall_initiation_date")
                    if date_val:
                        values.add(date_val)

                if not values:
                    fact_values[fact] = "ABSENT"
                elif len(values) == 1:
                    date_obj = parse_date(next(iter(values)))
                    if date_obj:
                        fact_values[fact] = [date_obj.strftime("%Y-%m-%d"), "fda_enforcement_reports"]
                    else:
                        fact_values[fact] = "ABSENT"
                else:
                    # Check if all values are the same after parsing
                    parsed_dates = set()
                    for val in values:
                        parsed = parse_date(val)
                        if parsed:
                            parsed_dates.add(parsed.strftime("%Y-%m-%d"))

                    if len(parsed_dates) == 1:
                        fact_values[fact] = [next(iter(parsed_dates)), "fda_enforcement_reports"]
                    else:
                        fact_values[fact] = "CONFLICT"

            elif fact == "classification date":
                values = set()
                for rec in records:
                    date_val = rec.get("center_classification_date")
                    if date_val:
                        values.add(date_val)

                if not values:
                    fact_values[fact] = "ABSENT"
                elif len(values) == 1:
                    date_obj = parse_date(next(iter(values)))
                    if date_obj:
                        fact_values[fact] = [date_obj.strftime("%Y-%m-%d"), "fda_enforcement_reports"]
                    else:
                        fact_values[fact] = "ABSENT"
                else:
                    # Check if all values are the same after parsing
                    parsed_dates = set()
                    for val in values:
                        parsed = parse_date(val)
                        if parsed:
                            parsed_dates.add(parsed.strftime("%Y-%m-%d"))

                    if len(parsed_dates) == 1:
                        fact_values[fact] = [next(iter(parsed_dates)), "fda_enforcement_reports"]
                    else:
                        fact_values[fact] = "CONFLICT"

            elif fact == "termination date":
                values = set()
                for rec in records:
                    date_val = rec.get("termination_date")
                    if date_val and date_val.strip():  # Only add non-empty values
                        values.add(date_val)

                if not values:
                    fact_values[fact] = "ABSENT"
                elif len(values) == 1:
                    date_obj = parse_date(next(iter(values)))
                    if date_obj:
