                        if parsed:
                            parsed_dates.add(parsed.strftime("%Y-%m-%d"))

                    if len(parsed_dates) == 1:
                        fact_values[fact] = [next(iter(parsed_dates)), "fda_enforcement_reports"]
                    else:
                        fact_values[fact] = "CONFLICT"

        results[pair] = fact_values

    return results

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_file = sys.argv[2]

    # Load manifest
    with open(manifest_file, 'r') as f:
        manifest = json.load(f)

    # Process pairs
    results = process_pairs(packet_dir, manifest)

    # Output results as JSON
    print(json.dumps(results, indent=2))

