import json
import os
import sys
from datetime import datetime
from pathlib import Path

def parse_date(date_str):
    """Parse date string in YYYYMMDD format to datetime.date object."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        return datetime.strptime(date_str.strip(), "%Y%m%d").date()
    except ValueError:
        return None

def load_fda_data(packet_dir):
    """Load FDA enforcement reports data from JSON file."""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r', encoding='utf-8') as f:
        data = json.load(f)

    # Create a mapping from recall_number to record
    records = {}
    for record in data.get("results", []):
        recall_num = record.get("recall_number", "").strip()
        if recall_num:
            records[recall_num] = record
    return records

def extract_fact_value(record, fact_name, rule_id):
    """Extract fact value from record based on fact name and rule."""
    if rule_id == "fda.classified_30d":
        if fact_name == "initiation date":
            date_str = record.get("recall_initiation_date", "")
            return parse_date(date_str)
        elif fact_name == "classification date":
            date_str = record.get("center_classification_date", "")
            return parse_date(date_str)
    elif rule_id == "fda.terminated_180d":
        if fact_name == "initiation date":
            date_str = record.get("recall_initiation_date", "")
            return parse_date(date_str)
        elif fact_name == "termination date":
            date_str = record.get("termination_date", "")
            return parse_date(date_str)
    return None

def format_date_for_output(date_obj):
    """Format datetime.date object to YYYY-MM-DD string."""
    if date_obj:
        return date_obj.strftime("%Y-%m-%d")
    return None

def process_pair(pair, records, facts_map):
    """Process a single rule_id::entity pair."""
    rule_id, entity = pair.split("::", 1)
    record = records.get(entity)

    if not record:
        # If no record found for this recall number, all facts are ABSENT
        return {fact: "ABSENT" for fact in facts_map[rule_id]}

    result = {}
    for fact_name in facts_map[rule_id]:
        value = extract_fact_value(record, fact_name, rule_id)
        if value is None:
            result[fact_name] = "ABSENT"
        else:
            formatted_value = format_date_for_output(value)
            result[fact_name] = [formatted_value, "fda_enforcement_reports"]

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    # Load FDA data
    records = load_fda_data(packet_dir)

    # Process all pairs
    output = {}
    for pair in manifest["pairs"]:
        output[pair] = process_pair(pair, records, manifest["facts"])

    # Print JSON output
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

