from pathlib import Path

def parse_date(date_str):
    """Parse date from various formats (YYYYMMDD, empty, etc.)"""
    if not date_str or date_str.strip() == "":
        return None
    try:
        # Handle YYYYMMDD format
        if len(date_str) == 8 and date_str.isdigit():
            return datetime.strptime(date_str, "%Y%m%d").date()
        # Handle other formats if present in data
        # For this case, we only expect YYYYMMDD based on the example
        return None
    except ValueError:
        return None

def load_fda_data(packet_dir):
    """Load FDA enforcement reports data"""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r') as f:
        data = json.load(f)

    # Create mapping from recall_number to record(s)
    records_by_recall = {}
    for record in data.get("results", []):
        recall_num = record.get("recall_number", "")
        if recall_num:
            if recall_num not in records_by_recall:
                records_by_recall[recall_num] = []
            records_by_recall[recall_num].append(record)

    return records_by_recall

def extract_fact_value(records, fact_name, entity):
    """Extract fact value according to decision rules"""
    if entity not in records:
        return "ABSENT"

    entity_records = records[entity]
    values = []

    for record in entity_records:
        if fact_name == "initiation date":
            value = record.get("recall_initiation_date", "")
        elif fact_name == "classification date":
            value = record.get("center_classification_date", "")
        elif fact_name == "termination date":
            value = record.get("termination_date", "")
        else:
            continue

        parsed = parse_date(value)
        if parsed:
            values.append((parsed, "fda_enforcement_reports"))

    if not values:
        return "ABSENT"

    # Check for conflicts
    unique_values = set(v[0] for v in values)
    if len(unique_values) > 1:
        return "CONFLICT"

    # Return value and document
    value_date, doc = values[0]
    return [str(value_date), doc]

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

