import json
import os
import sys
from datetime import datetime
from pathlib import Path

def parse_date(date_str):
    """Parse date string in YYYYMMDD format and convert to YYYY-MM-DD."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        # Parse from YYYYMMDD format
        date_obj = datetime.strptime(date_str.strip(), "%Y%m%d")
        # Convert to YYYY-MM-DD format
        return date_obj.strftime("%Y-%m-%d")
    except ValueError:
        return None

def load_fda_data(packet_dir):
    """Load FDA enforcement reports data from JSON file."""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r') as f:
        data = json.load(f)

    # Create mapping from recall_number to record(s)
    records = {}
    for record in data.get("results", []):
        recall_num = record.get("recall_number", "").strip()
        if recall_num:
            if recall_num not in records:
                records[recall_num] = []
            records[recall_num].append(record)
    return records

def extract_fact_value(record, fact_name):
    """Extract fact value from record based on fact name and format dates."""
    if fact_name == "initiation date":
        raw_value = record.get("recall_initiation_date", "")
    elif fact_name == "classification date":
        raw_value = record.get("center_classification_date", "")
    elif fact_name == "termination date":
        raw_value = record.get("termination_date", "")
    else:
        raw_value = ""

    # Convert date to YYYY-MM-DD format if it exists
    if raw_value:
        formatted_date = parse_date(raw_value)
        return formatted_date if formatted_date else raw_value
    return ""

def resolve_facts(records, fact_names):
    """Resolve facts for an entity with potentially multiple records."""
    fact_values = {}

    for fact_name in fact_names:
        values = []

        for record in records:
            value = extract_fact_value(record, fact_name)
            if value:  # Only consider non-empty values
                values.append(value)

        if not values:
            fact_values[fact_name] = "ABSENT"
        elif len(set(values)) == 1:
            fact_values[fact_name] = [values[0], "fda_enforcement_reports"]
        else:
            fact_values[fact_name] = "CONFLICT"

    return fact_values

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    # Load FDA data
    fda_records = load_fda_data(packet_dir)

    # Process each pair
    result = {}
    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)
        fact_names = manifest["facts"][rule_id]

        if entity not in fda_records:
            # Entity not found in records
            fact_values = {fact_name: "ABSENT" for fact_name in fact_names}
        else:
            fact_values = resolve_facts(fda_records[entity], fact_names)

        result[pair] = fact_values

    # Output result as JSON
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

